<?php ob_start();$qs=$filters??[]; ?><div class="admin-toolbar"><div><p class="eyebrow">CATÁLOGOS AUXILIARES</p><p class="muted">Administra <?=$meta['title']?> sin modificar la base de datos.</p></div><a class="admin-button primary" href="<?=url('admin/'.$meta['slug'].'/crear')?>">＋ <?=$meta['create']?></a></div><form class="admin-filter-form" method="get" action="<?=url('admin/'.$meta['slug'])?>"><input type="search" name="q" maxlength="100" value="<?=e($qs['q']??'')?>" placeholder="Buscar por nombre o slug"><select name="active"><option value="">Todos los estados</option><option value="1" <?=($qs['active']??'')==='1'?'selected':''?>>Activos</option><option value="0" <?=($qs['active']??'')==='0'?'selected':''?>>Inactivos</option></select><select name="sort"><option value="name_asc">Nombre A-Z</option><option value="newest" <?=($qs['sort']??'')==='newest'?'selected':''?>>Más recientes</option><option value="used" <?=($qs['sort']??'')==='used'?'selected':''?>>Más utilizados</option></select><button class="admin-button secondary">Filtrar</button></form><section class="panel"><div class="panel-heading"><h2><?= (int)$result['total']?> <?=$meta['title']?></h2></div><?php if(!$result['items']):?><div class="empty-state"><strong>No encontramos registros con estos filtros.</strong><p>Puedes crear el primero desde este módulo.</p></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Nombre</th><th>Slug</th><?php if($type==='brand'):?><th>País</th><?php endif;?><th>Perfumes</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($result['items'] as $row):?><tr><td><strong><?=e($row['name'])?></strong></td><td><small><?=e($row['slug'])?></small></td><?php if($type==='brand'):?><td><?=e($row['country']??'—')?></td><?php endif;?><td><?= (int)$row['related_count']?></td><td><span class="status-pill <?=$row['is_active']?'status-publicado':'status-archivado'?>"><?=$row['is_active']?'Activo':'Inactivo'?></span></td><td class="table-actions"><a href="<?=url('admin/'.$meta['slug'].'/'.$row['id'])?>">Ver</a><a href="<?=url('admin/'.$meta['slug'].'/'.$row['id'].'/editar')?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($result['pages']>1):?><nav class="pagination" aria-label="Paginación"><?php for($n=1;$n<=$result['pages'];$n++){$p=$qs;$p['page']=$n;?><a class="<?=$n===$result['page']?'current':''?>" href="<?=build_query_url('admin/'.$meta['slug'],$p)?>"><?=$n?></a><?php }?></nav><?php endif;?></section><?php $content=ob_get_clean();$section=$meta['slug'];require dirname(__DIR__).'/layouts/main.php';?>
